            \textbf{Tan} & + & - & + & - \\
            \hline
        \end{tabular} &
        The above information can be conveniently remembered with the phrase "Add Sugar To Coffee"
    \end{tabularx}
    \item \textbf{Allied Angles:}
    \begin{enumerate}[label=\alph*)]
        \item $\sin(90^\circ - \theta) = \cos\theta$
        \item $\cos(90^\circ - \theta) = \sin\theta$
        \item $\tan(90^\circ - \theta) = \cot\theta$
        \item $\cot(90^\circ - \theta) = \tan\theta$
        \item $\sec(90^\circ - \theta) = \csc\theta$
        \item $\csc(90^\circ - \theta) = \sec\theta$
    \end{enumerate}
    \item \textbf{Compound Angles:}
    \begin{align*}
        \sin(A + B) &= \sin A \cos B + \cos A \sin B \\
        \sin(A - B) &= \sin A \cos B - \cos A \sin B \\
        \cos(A + B) &= \cos A \cos B - \sin A \sin B \\
        \cos(A - B) &= \cos A \cos B + \sin A \sin B \\
        \tan(A + B) &= \frac{\tan A + \tan B}{1 - \tan A \tan B} \\
        \tan(A - B) &= \frac{\tan A - \tan B}{1 + \tan A \tan B}
    \end{align*}
    \item \textbf{Multiple Angle and Sub Multiple Angle:}
    \begin{enumerate}[label=\roman*)]
        \item $\sin 2A = 2 \sin A \cos A$
        \item $\cos 2A = \cos^2 A - \sin^2 A$
        \item $\cos 2A = 2 \cos^2 A - 1$
        \item $\cos 2A = 1 - 2 \sin^2 A$
        \item $\cos A = \frac{1 - \tan^2 \frac{A}{2}}{1 + \tan^2 \frac{A}{2}}$
        \item $\sin A = \frac{2 \tan \frac{A}{2}}{1 + \tan^2 \frac{A}{2}}$
        \item $\tan A = \frac{2 \tan \frac{A}{2}}{1 - \tan^2 \frac{A}{2}}$
    \end{enumerate}
\end{enumerate}

\section{Co-Ordinate Geometry (2D)}

\begin{enumerate}[label=\arabic*)]
    \item \textbf{Distance Formula:} $(x_2 - x_1)^2 + (y_2 - y_1)^2$
    \item \textbf{Section Formula:} $\left(\frac{mx_2 + nx_1}{m + n}, \frac{my_2 + ny_1}{m + n}\right)$
    \item \textbf{Mid Point Formula:} $\left(\frac{x_1 + x_2}{2}, \frac{y_1 + y_2}{2}\right)$
    \item \textbf{Centroid of Triangle:} $G\left(\frac{x_1 + x_2 + x_3}{3}, \frac{y_1 + y_2 + y_3}{3}\right)$
    \item \textbf{Area of Triangle:} $\Delta = \frac{1}{2} |x_1(y_2 - y_3) + x_2(y_3 - y_1) + x_3(y_1 - y_2)|$
    \item \textbf{Slope of straight line:} $m = \frac{y_2 - y_1}{x_2 - x_1}$
    \item \textbf{One point Form:} $y - y_1 = m(x - x_1)$
    \item \textbf{Slope Intercept Form:} $y = mx + c$
    \item \textbf{Two point Form:} $\frac{y - y_1}{x - x_1} = \frac{y_2 - y_1}{x_2 - x_1}$
    \item \textbf{Intercept Form:} $\frac{x}{a} + \frac{y}{b} = 1$
    \item \textbf{Normal Form:} $x \cos \alpha + y \sin \alpha = p$
    \item \textbf{Slope of line:} $m = \tan \alpha$
    \item \textbf{Intersection of two lines:} $L_1 \perp L_2 \implies m_1 m_2 = -1$
    \item \textbf{Angle between two straight lines:} $\tan \theta = \left|\frac{m_1 - m_2}{1 + m_1 m_2}\right|$
    \item \textbf{If the lines are parallel:} $m_1 = m_2$
    \item \textbf{If the lines are perpendicular:} $m_1 m_2 = -1$
    \item \textbf{Length of perpendicular from a point to a line:} $d = \frac{|ax_1 + by_1 + c|}{\sqrt{a^2 + b^2}}$
    \item \textbf{Bisector Equations:} $\frac{ax + by + c}{\sqrt{a^2 + b^2}} = \pm \frac{a'x + b'y + c'}{\sqrt{a'^2 + b'^2}}$
    \item \textbf{Distance between parallel lines:} $d = \frac{|c - c'|}{\sqrt{a^2 + b^2}}$
    \item \textbf{Homogeneous Equation:} $ax^2 + 2hxy + by^2 = 0$
    \item \textbf{General Equation:} $ax^2 + 2hxy + by^2 + 2gx + 2fy + c = 0$
    \item If $ab - h^2 = 0$, the general equation represents a pair of lines.
    \item If $ab - h^2 > 0$, the general equation represents an ellipse.
    \item If $ab - h^2 < 0$, the general equation represents a hyperbola.
    \item If $a = b$ and $h = 0$, the general equation represents a circle.
\end{enumerate}

\section{Co-Ordinate Geometry (3D)}

\begin{enumerate}[label=\arabic*)]
    \item \textbf{Distance Formula:} $\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2 + (z_2 - z_1)^2}$
    \item \textbf{Section Formula:} $\left(\frac{mx_2 + nx_1}{m + n}, \frac{my_2 + ny_1}{m + n}, \frac{mz_2 + nz_1}{m + n}\right)$
\end{enumerate}

